      "path": "packages/dsh-web-all/cordis.patch.yml",
      "content": "# AUTO-GENERATED by scripts/aggregate.mjs — do not edit\n# This file is derived from the aggregate.yml manifest in this package;\n# edit aggregate.yml and rerun `node scripts/aggregate.mjs`.\n# Rows are namespaced web-ui-* so the bundle can coexist with standalone installs.\n# Family rows mount the real plugin package: the loader then serves that package's\n# own browser half, and one family switch is one loader switch.\n\n# from self\n- insert:\n    - id: web-ui-compat\n      name: '@linxin666/dsh-web-all'\n\n# from ../dsh-web-settings\n- insert:\n    - id: web-ui-settings\n      name: '@linxin666/dsh-client-ui-web-ui-settings'\n\n# from ../dsh-plugin-manager\n- insert:\n    - id: web-ui-plugin-manager\n      name: '@linxin666/dsh-client-ui-plugin-manager'\n\n# from ../dsh-plugin-manager (patch row ui-settings-plugins)\n- id: ui-settings-plugins\n  disabled: true\n\n# from ../dsh-market\n- insert:\n    - id: web-ui-market\n      name: '@linxin666/dsh-client-ui-market'\n\n# from ../dsh-task-board\n- insert:\n    - id: web-ui-task-board\n      name: '@linxin666/dsh-client-ui-task-board'\n\n# from ../dsh-task-board-github\n- insert:\n    - id: web-ui-task-board-github\n      name: '@linxin666/dsh-client-ui-task-board-github'\n\n# from ../dsh-task-board-team\n- insert:\n    - id: web-ui-task-board-team\n      name: '@linxin666/dsh-client-ui-task-board-team'\n\n# from ../dsh-agents\n- insert:\n    - id: web-ui-agents\n      name: '@linxin666/dsh-agents'\n\n# from ../dsh-remote-bridge\n- insert:\n    - id: web-ui-remote-bridge\n      name: '@linxin666/dsh-remote-bridge'\n\n# from ../dsh-task-board-remote\n- insert:\n    - id: web-ui-task-board-remote\n      name: '@linxin666/dsh-task-board-remote'\n\n# from ../dsh-ssh\n- insert:\n    - id: web-ui-ssh\n      name: '@linxin666/dsh-ssh'\n\n# from ../dsh-liangshen\n- insert:\n    - id: web-ui-liangshen\n      name: '@linxin666/dsh-liangshen'\n\n# from ../dsh-skill-explorer\n- insert:\n    - id: web-ui-skill-explorer\n      name: '@linxin666/dsh-client-ui-skill-explorer'\n\n# from ../dsh-usage\n- insert:\n    - id: web-ui-usage\n      name: '@linxin666/dsh-usage'\n\n# from ../dsh-session-archive\n- insert:\n    - id: web-ui-session-archive\n      name: '@linxin666/dsh-session-archive'\n\n# from ../dsh-message-edit\n- insert:\n    - id: web-ui-message-edit\n      name: '@linxin666/dsh-client-ui-message-edit'\n\n# from ../dsh-win-bash\n- insert:\n    - id: web-ui-win-bash\n      name: '@linxin666/dsh-win-bash'\n      disabled: !!js process.platform !== 'win32'\n\n# from ../dsh-i18n\n- insert:\n    - id: web-ui-i18n\n      name: '@linxin666/dsh-i18n'\n\n# from ../dsh-diagrams\n- insert:\n    - id: web-ui-diagrams\n      name: '@linxin666/dsh-client-ui-diagrams'\n\n# from ../dsh-browser-view\n- insert:\n    - id: web-ui-browser-view\n      name: '@linxin666/dsh-client-ui-browser-view'\n\n# inactive by default (opt-in rows): these ship disabled; each is enabled per row in the\n# plugin manager, whose enable writes a user-layer \"disabled: false\" override that wins.\n- id: web-ui-ssh\n  disabled: true\n- id: web-ui-skill-explorer\n  disabled: true\n\n# external bundle: @linxin666/dsh-client-ui-community-plugins\n\n# from external bundle @linxin666/dsh-client-ui-community-plugins (insert row web-ui-community-plugins)\n- insert:\n    - id: web-ui-community-plugins\n      name: '@linxin666/dsh-client-ui-community-plugins'\n\n# external bundle: @linxin666/dsh-pet\n\n# from external bundle @linxin666/dsh-pet (insert row web-ui-pet)\n- insert:\n    - id: web-ui-pet\n      name: '@linxin666/dsh-pet'\n\n# external bundle: @linxin666/dsh-client-ui-preset-center\n\n# from external bundle @linxin666/dsh-client-ui-preset-center (insert row web-ui-preset-center)\n- insert:\n    - id: web-ui-preset-center\n      name: '@linxin666/dsh-client-ui-preset-center'\n\n# external bundle: @linxin666/dsh-client-ui-skin-center\n\n# from external bundle @linxin666/dsh-client-ui-skin-center (insert row web-ui-skin-center)\n- insert:\n    - id: web-ui-skin-center\n      name: '@linxin666/dsh-client-ui-skin-center'\n"
